with ins as (insert into public.artist_press (artist_id,artist_slug,title,publication,url,date_published,type) select a.id,x.s,x.t,x.p,x.u,x.d::date,'feature' from json_to_recordset('[{"s":"prismer","t":"Wild City #148: Rohan Kale","p":"Wild City","u":"https://www.thewildcity.com/mixes/6930-wild-city-148-rohan-kal","d":"2018-04-13"},{"s":"prismer","t":"Prismer Traxx","p":"Zeitgeister (Goethe-Institut)","u":"https://www.goethe.de/prj/zei/en/exp/25808212.html","d":null},{"s":"prismer","t":"Electrifying nights await: G5A''s Port After Dark with DJ Nariki and Prismer","p":"The Indian Music Diaries","u":"https://theindianmusicdiaries.com/electrifying-nights-await-g5as-port-after-dark-with-dj-nariki-prismer/","d":"2025-01-30"},{"s":"dj-pants","t":"Wild City #242: DJ Pants","p":"Wild City","u":"https://www.thewildcity.com/mixes/20911-wild-city-242-dj-pants","d":"2024-10-23"},{"s":"bawra","t":"Wild City #264: Baawra","p":"Wild City","u":"https://www.thewildcity.com/mixes/21835-wild-city-264-baawra","d":"2026-09-18"},{"s":"thegreybox","t":"Wild City Singled Out: September 2019","p":"Wild City","u":"https://www.thewildcity.com/features/15432-wild-city-singled-out-september-2019","d":"2019-11-02"},{"s":"thegreybox","t":"A Comprehensive Guide To The Music At Magnetic Fields 2019","p":"Wild City","u":"https://www.thewildcity.com/features/15842-a-comprehensive-guide-to-the-music-at-magnetic-fields-2019","d":"2019-12-11"}]'::json) as x(s text,t text,p text,u text,d text) join public.artists a on a.slug=x.s on conflict (artist_slug,url) do nothing returning 1) select count(*) from ins;